pages=[]
def code(s,lang='text'): return f'<div class="code-label">{lang} · design skeleton</div><pre><code>{html.escape(s.strip())}</code></pre>'
def table(head,rows): return '<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+x+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def call(title,s): return f'<aside class="callout"><strong>{title}</strong><p>{s}</p></aside>'
def section(title,s): return '<section class="doc-section"><h2>'+title+'</h2>'+s+'</section>'
def add(slug,title,kicker,summary,body,prompt,group='Design'): pages.append(dict(slug=slug,title=title,kicker=kicker,summary=summary,body=body,prompt=prompt,group=group))
def flow(nodes): return '<div class="flow">'+''.join('<div class="flow-step"><span>'+str(i+1).zfill(2)+'</span><strong>'+a+'</strong><p>'+b+'</p></div>' for i,(a,b) in enumerate(nodes))+'</div>'
def sources(items): return '<ul class="sources">'+''.join(f'<li><a href="{u}" target="_blank" rel="noopener">{n} ↗</a></li>' for n,u in items)+'</ul>'
baseprompt='''Context: build a thin, synthetic-data Customer Data Federation prototype for a bank. Three separate CockroachDB clusters in SG, United Kingdom (UK) and US; one home writer per customer; local multi-AZ HA; asynchronous approved projections. No customer data or customer-linked metadata in excluded regions. Use Java/Spring Boot, PostgreSQL JDBC, OPA/Rego v1, regional Kafka and OpenTelemetry. This is a component implementation task, not permission to deploy production infrastructure or use real bank data. Inspect existing repositories and preserve module ownership. Pin compatible versions and licences before implementation. Deliver interfaces, small adapters, migrations/configuration where needed, meaningful tests, an ADR and run instructions. Never claim tests passed unless run.\n\n'''
add('index','Customer data, within its boundaries.','Architecture / Design edition 03','A bank federation blueprint: three regional cells, one authoritative home per customer, and explicit permission at every crossing.',
'''<div class="hero-diagram" role="img" aria-label="SG authoritative customer data replicated to United Kingdom when authorised, with US explicitly excluded"><div class="region home"><span class="eyebrow">AUTHORITATIVE HOME</span><h3>Singapore</h3><p>Customer C-001 · version 42</p><div class="nodes"><i></i><i></i><i></i></div><small>3 zones · local quorum</small></div><div class="bridge"><span>OPA permits</span><b>→</b><small>Approved fields only</small></div><div class="region"><span class="eyebrow">PERMITTED PROJECTION</span><h3>United Kingdom</h3><p>Servicing · eventually consistent</p><div class="nodes"><i></i><i></i><i></i></div><small>3 zones · local quorum</small></div><div class="region excluded"><span class="eyebrow">EXPLICIT EXCLUSION</span><h3>United States</h3><p>No customer record, queue item or directory entry</p><strong>DENY</strong></div></div>
<div class="metric-strip"><div><b>03</b><span>Independent regional cells</span></div><div><b>01</b><span>Home writer per customer</span></div><div><b>OPA</b><span>Policy decisions close to work</span></div><div><b>OTel</b><span>Regional operational evidence</span></div></div>
'''+section('Start with a decision, then explore the implementation', '''<div class="link-grid"><a href="control-plane.html"><span>01 / EXPERIENCE</span><h3>Explore the control plane →</h3><p>Customer residency, policy simulation, approvals and revocation.</p></a><a href="gateways.html"><span>02 / REQUEST PATH</span><h3>Follow a business API →</h3><p>Regional ingress, OPA checks and a home-region transaction.</p></a><a href="engineering.html"><span>03 / DELIVERY</span><h3>Start the prototype →</h3><p>Bounded engineering prompts, dependency order and acceptance gates.</p></a></div>''')+
section('Decisions that shape the system',table(['Decision','Chosen design','Consequence'],[
['Database topology','One CockroachDB cluster per geographic region','Local ACID and clear boundaries; no cross-cluster ACID.'],['Policy','Rego rule bundles + authoritative JSON facts','OPA decides; services enforce, transact and fence.'],['Business service shape','Regional modular service for operations that share invariants','In-process orchestration and one JDBC transaction; separate deployment only where useful.'],['Federation','Transactional outbox → local CDC → export gate → destination importer','Home writes do not wait for WAN; remote data carries freshness.'],['Gateway routing','Explicit regional endpoints; customer-aware home routing inside permitted cells','No global body-terminating proxy or customer directory by default.'],['Observability','Regional OTel agents and collector gateways','Raw telemetry remains regional; only approved non-customer aggregates may leave.']]))+
call('Design site, not a connected bank platform','All customers, telemetry and operations on this site are synthetic. Interactive screens run in your browser and reset on reload. The code samples are engineering skeletons; no bank services, OPA engine or databases are running here.'),
baseprompt+'Read all component pages and produce the minimal architecture skeleton with their contracts. Preserve the separation between regional HA, customer residency and business access. Start with one SG-home customer, one UK projection and US exclusion. Do not add active-active customer writes or global transaction coordination.',group='Explore')

add('architecture','Three cells. Deliberate crossings.','System architecture','A regional cell is the unit of deployment, failure containment and operational custody.',
section('Deployment topology', '''<div class="architecture-grid">'''+''.join(f'''<div class="cell"><span class="eyebrow">{r} CELL</span><h3>{name}</h3><div class="cell-layer">Regional gateway + local OPA</div><div class="cell-layer">Business API / policy authority / workers</div><div class="cell-layer">CockroachDB × 3 zones</div><div class="cell-layer">Kafka / regional keys / backup vault</div><div class="cell-layer">OTel collectors / audit archive</div></div>''' for r,name in [('SG','Singapore'),('UK','United Kingdom'),('US','United States')])+'''</div><p>Only export workers and narrowly scoped command routers have cross-region access. Each crossing requires permitted source, destination, service, dataset, purpose and policy generation. Independent database credentials prevent regional applications from querying another cluster directly.</p>''')+
section('Component ownership',table(['Plane','Components','Custody'],[
['Control','Policy API, approval workflow, entitlement adapter, desired-state reconciler','Customer policy authority lives with the home record. Regional UX backends expose only authorised views.'],['Business','Customer servicing API, command orchestrator, projection query API','Each deployment serves its own region. Business state commits at home.'],['Federation','Outbox, CDC relay, Kafka, export gate, importer and fences','Source queues remain at source; receiver persists only authorised payloads.'],['Operations','OPA bundle service, OTel collectors, evidence archive','Generic code may be global. Customer-linked evidence and facts remain constrained.']]))+
section('What is global—and what is not', '<p>The global ID is a stable opaque UUID used wherever a customer is authorised. It is not a reason to replicate a universal customer directory. Generic schemas, service discovery and Rego rules can be shared. Customer IDs, entitlements, audit events, hashes and trace correlations can still be identifying and follow their own approved residency rules.</p><p>Control-plane administrators use a regional entry point and regional BFF. A global fleet view shows infrastructure health aggregates only. A customer view is fetched only from an authorised region and only for an operator allowed to process that customer there.</p>')+
section('Availability contract', table(['Fault','Behaviour'],[['One node or AZ','Surviving local quorum and provisioned capacity keep the cell serving. Test the actual placements.'],['WAN partition','Home writes continue. Federation backlog grows locally. Expired remote read leases fail closed.'],['Home region lost','Authoritative writes stop. No automatic promotion of an asynchronous projection.'],['OPA absent or invalid rule bundle','Affected requests fail closed. Readiness removes unsafe instances.'],['Bundle distribution unavailable','Last verified rule bundle may run only within configured freshness limits; expiring customer facts remain enforced.']]))+
call('No silent disaster-recovery exception','A SG-only customer cannot be recovered in the US merely because SG is down. Promotion needs allowed placement, old-writer fencing, a new home epoch and an accepted RPO; it is outside the thin PoC.')+
section('Native database placement alternative','<p>A single multi-region CockroachDB cluster can constrain regional-table replicas using super regions. That is a valid option for stable residency cohorts and a shared SQL boundary, but it does not replace entitlement processing or safe exports. Separate regional clusters simplify this design’s dynamic exclusions.</p>'+sources([('CockroachDB data domiciling','https://www.cockroachlabs.com/docs/stable/data-domiciling'),('Production checklist','https://www.cockroachlabs.com/docs/stable/recommended-production-settings')])),
baseprompt+'Implement only the regional infrastructure skeleton. Provide three isolated networks and independently identified CockroachDB clusters. Supply a lightweight laptop profile and a separate nine-node/three-zone HA test profile; do not confuse simulated geography with residency proof. Prevent cross-region SQL and unapproved topic mirroring. Include regional storage and observability boundaries plus a fault matrix.')

add('gateways','Every request has a regional entry.','Component / Gateways & service deployment','Deploy the same business service image in each region; route according to operation and authority, not the nearest writable copy.',
section('Deployment and access',table(['Endpoint / layer','Deployment','Access rule'],[
['api.sg.bank.example','Regional private load balancer → Envoy gateway replicas across SG zones','OIDC for people, OAuth client credentials for trusted clients; TLS terminates in SG.'],['api.uk.bank.example / api.us.bank.example','Equivalent regional gateways','No GeoDNS fallback that sends request bodies to an excluded geography.'],['Business API','Kubernetes Deployment, ≥3 replicas across zones, ClusterIP only','Gateway identities allowed; applications recheck customer-level permissions.'],['Federation ingress','Separate internal regional listener and importer','mTLS, narrow exporter identities, signed destination-bound permits.'],['Control-plane BFF','Regional administrative service behind admin gateway','Step-up auth and operator scope; customer data is not collected by a universal BFF.'],['Service-to-service','Private service DNS; mTLS workload identity','Network policy prevents bypass. No need for a full service mesh in the first PoC.']]))+
section('Request sequence: UK user updates a Singapore-home customer',flow([
['Enter the UK','Authenticated user calls the UK gateway; the customer must already be permitted for UK processing.'],['Coarse admission','Envoy authenticates, normalises paths and asks local OPA about caller, route, method and service.'],['Resolve locally','UK service checks its permitted routing metadata, customer policy and command purpose. Unknown customer: generic denial; no global lookup.'],['Route command to SG','A private router uses mTLS and delegated caller context. It rechecks export of command fields and never relays through US.'],['Commit at home','SG service reauthorises from current facts and commits business state, idempotency result, audit intent and outbox together.'],['Return intentionally','Return operation ID/version and only UK-permitted fields. UK projection catches up asynchronously; no false read-your-write promise.']]))+
section('Read and write behaviours',table(['Operation','Path','Response'],[
['Local permitted read','Regional gateway → local service → local projection','Allowed fields + sourceVersion + replicatedAt + max-staleness check.'],['Fresh authoritative read','Authorised router → home service','WAN latency accepted; do not return fields the requesting region cannot process.'],['Business command','Home orchestrator only','200/201 for completed home commit; version returned. Retry requires idempotency key.'],['Grant / revoke','Home control API','202 + operation ID; lifecycle is asynchronous.'],['Remote projection not caught up','Local service','Expose stale/pending status; optional explicit home read if permitted.']]))+
section('Gateway enforcement skeleton',code('''# Envoy filter fragment; complete listener/cluster/TLS config is an extension point.
name: envoy.filters.http.ext_authz
typed_config:
  "@type": type.googleapis.com/envoy.extensions.filters.http.ext_authz.v3.ExtAuthz
  grpc_service:
    envoy_grpc:
      cluster_name: local_opa
    timeout: 0.050s
  failure_mode_allow: false
  transport_api_version: V3
# Also configure trusted JWT verification, path normalisation, rate limits,
# request size bounds, allow-listed headers and sanitised access logs.''','YAML')+'<p>Do not treat a user-supplied X-Region or customer ID header as trusted policy input. Derive execution region from deployment configuration, caller from verified identity and destination from the fixed route. Avoid sending full request bodies to gateway OPA. The service handles fields and business facts.</p>')+
section('Why two enforcement points?','<p>Gateway OPA protects entry to the API. Service OPA handles resource, purpose and field decisions using trusted facts. A gateway allow decision does not authorise arbitrary customer records. Direct service access is restricted, but the service still enforces customer policy.</p>'+sources([('OPA–Envoy integration','https://www.openpolicyagent.org/docs/envoy')])),
baseprompt+'Implement a regional Envoy gateway skeleton with local OPA-Envoy ext_authz, plus a Spring Boot business API with resource-level OPA enforcement. Verify JWTs before policy evaluation; normalise paths; fail closed; never trust user-provided regional claims. Provide local read and home-command routing contracts, response-field filtering, delegated identity, idempotency and timeout handling. Test gateway bypass, spoofed region headers, expired identity, OPA failure, path-encoding ambiguity and excluded-region command responses.')

rego='''package bank.federation
import rego.v1

default allow := false

allow if {
    input.operation == "replicate"
    input.source_region == input.policy.home_region
    input.destination_region in input.policy.allowed_storage_regions
    input.destination_region in input.policy.allowed_processing_regions
    not input.destination_region in input.policy.denied_regions
    input.grant.region == input.destination_region
    input.grant.service == input.service
    input.grant.purpose == input.purpose
    input.grant.dataset == input.dataset
    input.grant.generation >= input.minimum_generation
    input.policy.version == input.required_policy_version
    input.now_ns < input.grant.expires_at_ns
    input.now_ns < input.facts_valid_until_ns
    input.facts_verified == true
    input.bundle_compatible == true
}

permitted_fields := {f |
    allow
    some f in input.grant.fields
    f in input.policy.exportable_fields
    not f in input.policy.denied_fields
}

decision := {
    "allow": allow,
    "fields": permitted_fields,
    "policy_version": input.policy.version,
    "grant_generation": input.grant.generation,
}'''
add('opa','Rules in Rego. Facts under regional custody.','Component / OPA policy platform','OPA becomes the decision engine. It is not the transaction manager, entitlement source or replication coordinator.',
section('Policy format and ownership',table(['Artefact','Format','Distribution'],[
['Rule logic','Rego v1, Git-reviewed; package bank.federation / bank.access / bank.admin','Signed, versioned bundles containing generic logic; region-scoped exceptions if needed.'],['Customer facts','JSON validated against JSON Schema','Authoritative home database; scoped facts passed by trusted service, not client.'],['Entitlements','JSON with region, service, purpose, dataset, fields, generation, expiry','Only to destinations that legitimately hold or are being granted a copy.'],['Decision','JSON: allow, fields, policy version, grant generation, reason codes','Consumed by the policy enforcement point; masked regional audit.'],['Policy authoring UX','Form and JSON preview; no arbitrary Rego editing by operators','Business policy changes follow maker–checker and version checks.']]))+
section('Evaluation contract',code('''POST http://127.0.0.1:8181/v1/data/bank/federation/decision
{
  "input": {
    "operation": "replicate",
    "source_region": "SG",
    "destination_region": "UK",
    "service": "customer-servicing",
    "purpose": "account-support",
    "dataset": "customerProfile",
    "policy": { "version": 12, "home_region": "SG",
      "allowed_storage_regions": ["SG", "UK"],
      "allowed_processing_regions": ["SG", "UK"],
      "denied_regions": ["US"],
      "exportable_fields": ["customerId", "displayName"],
      "denied_fields": [] },
    "grant": { "region": "UK", "service": "customer-servicing",
      "purpose": "account-support", "dataset": "customerProfile",
      "fields": ["customerId", "displayName"], "generation": 3,
      "expires_at_ns": 1791676800000000000 },
    "required_policy_version": 12, "minimum_generation": 3,
    "now_ns": 1791633600000000000,
    "facts_valid_until_ns": 1791633630000000000,
    "facts_verified": true, "bundle_compatible": true
  }
}''','JSON')+'<p>These fields are populated by the enforcement adapter from verified identity, deployment settings and current database/lease state. The Booleans are adapter assertions, never client claims. Nanosecond timestamps require an integer-safe server serializer.</p>')+
section('Rego decision skeleton',code(rego,'Rego v1')+call('Scope of this skeleton','This demonstrates a single grant for one dataset. Production extension points: schema validation, missing-field handling, stable reason codes, multiple-grant union, deny overlays, home migrations and clock-skew bounds. An undefined result is a denial, not an allow.'))+
section('Bundle lifecycle and consistency',flow([['Build','opa fmt, opa check --strict, opa test; reject failing deny and expiry tests.'],['Sign','CI signs an immutable rule bundle; publish to regional bundle services with fixed signing-key trust.'],['Canary','Replay synthetic decisions against candidate; compare allowed fields and reasons.'],['Activate','Observe bundle revision from each OPA instance; readiness requires a compatible verified revision.'],['Rollback','Revert rule code after review; never roll back customer facts or revocation generations.']]))+'<p>OPA bundle updates are eventually consistent. A successful publication is not proof every sidecar is updated. Track rule revision separately from customer policy version, grant generation and home epoch. Short-lived signed fact leases and durable fences bound stale authorisation; pushing a new bundle alone cannot revoke instantly.</p>'+
section('Runtime performance choices','<p>Run OPA next to each service/exporter and OPA-Envoy next to the gateway. Evaluate locally without decision-time HTTP calls to external entitlement sources. Keep customer facts out of broad bundles; pass only required trusted facts. Cache generic rules aggressively, but do not cache allow decisions beyond the fact lease. Changes to policy version or grant generation invalidate cached decisions.</p>'+sources([('OPA bundles and eventual consistency','https://www.openpolicyagent.org/docs/management-bundles'),('OPA configuration and signing','https://www.openpolicyagent.org/docs/configuration'),('OPA decision log masking','https://www.openpolicyagent.org/docs/management-decision-logs')])),
baseprompt+'Create the OPA rule package with Rego v1 and JSON Schema input/output contracts. Start from the federation skeleton on this page; implement stable deny reasons and multiple-grant field union with overriding denials. Separate generic signed bundles from customer-specific facts. Add tests for missing fields, US deny overriding allow, expired facts/grants, generation rollback, service/purpose mismatch, field narrowing and bundle compatibility. Configure bundle signing verification and masked decision logs. Integrate actual opa test in CI. Do not present a browser JavaScript simulation as a real OPA evaluation.')

add('transactions','Keep invariants together. Move copies asynchronously.','Technical design / Transaction boundaries','One local serializable transaction for the business operation; no WAN call while holding a database transaction.',
section('Chosen transaction boundaries',table(['Boundary','Atomic contents','Outside the transaction'],[
['Home business command','Idempotency key/result + customer aggregate + business invariants + version increment + audit intent + outbox','OPA RPC is evaluated before transaction on versioned facts; validate those versions in transaction. Kafka and cross-region calls follow commit.'],['Home policy change','Policy version + grant generation + desired placement + reconciliation job + audit intent','Bundle distribution, remote fences and deletion acknowledgements.'],['Destination apply','Inbox uniqueness + fence/version validation + projection replace + applied checkpoint + audit intent','Network acknowledgement after commit.'],['Destination revoke','Increase fence generation + block reads/imports + delete live projection + purge job/audit intent','Backup/history disposal and evidence collection.'],['Multi-domain command in one home','Shared transaction through in-process module interfaces where invariants require it','External effects via outbox/saga; no distributed pretend rollback.']]))+
section('Why a modular business service?','<p>Deploy a regional customer-operations service with domain modules for customer profile, contact preference and servicing entitlement workflows. Each module can originate in a separate repository and publish a versioned library. The home orchestrator composes modules in one process with one transaction context, reducing network handoffs without flattening domain ownership.</p><p>Keep federation, policy bundle publishing and telemetry as separate workers/processes because their failure and scaling characteristics differ. Avoid proliferating REST calls inside a business transaction. Cross-home operations use an explicit saga or reservation workflow; a “try/commit” API across clusters is not an ACID guarantee.</p>')+
section('Safe evaluation around a transaction',code('''facts = policyRepository.readCurrent(customerId)
decision = localOpa.evaluate(command, facts)
requireAllow(decision)

retrySerializable(() -> {
  current = tx.readPolicyAndWriterEpoch(customerId)
  require(current.version == facts.version)
  require(current.homeEpoch == expectedHomeEpoch)
  require(current.grantGeneration == facts.grantGeneration)
  requireValidExpiryAndRegion(current)
  if (tx.hasIdempotencyResult(caller, key)) return storedResult
  updated = domain.apply(command, expectedAggregateVersion)
  tx.save(updated)
  tx.insertOutbox(eventId, updated.version, projectionSnapshot)
  tx.insertAuditIntent(decisionId, current.version)
  tx.saveIdempotencyResult(caller, key, requestHash, result)
})
# Changed facts => re-read and re-evaluate, not retry stale permission.
# Retry budget exceeded => explicit retriable failure.
# Never call Kafka or a remote API inside retryable transaction body.''','Pseudocode'))+
section('Performance budgets to measure',table(['Measure','Initial target','Design response'],[
['Local OPA evaluation','p95 ≤5 ms under agreed load','Local facts, indexed policy data; profile rules before adding caches.'],['Local read API','p95 ≤100 ms at 100 req/s per cell','Connection pools bounded to DB capacity; return only needed fields.'],['Home write API','p95 ≤200 ms locally','Small aggregates and transactions; contention/retry metrics.'],['Healthy federation lag','p95 ≤5 s at 20 updates/s','Batch transport, customer-key partitioning, parallelism across customers.'],['Remote read lease','Provisional 30 s + explicit clock-skew allowance','Bounded revocation window; security trade-off exposed in UX.'],['Home-routed UK command','Local processing budget + measured WAN round trips','No invented global latency guarantee.']]))+call('Targets, not results','Use 10,000 synthetic customers and roughly 2 KB projections for the first load run. Report percentiles, contention, queue lag and CPU. Change budgets only with evidence; prioritise exclusions and correctness over throughput.')+
section('Concurrency and correctness','<p>Use SERIALIZABLE for home writes and policy/fence operations. Handle SQLSTATE 40001 through bounded retry with jitter. Idempotency keys are scoped to caller and operation and include a request hash; key reuse with different content is a conflict. A home epoch prevents stale writers after future promotion. Use aggregate versions for data and grant generations for authority; neither substitutes for the other.</p>'+sources([('CockroachDB transaction retries','https://www.cockroachlabs.com/docs/stable/transaction-retry-error-reference'),('CockroachDB changefeed ordering','https://www.cockroachlabs.com/docs/stable/changefeed-messages')])),
baseprompt+'Implement one customer business command using a modular Spring Boot service and a single CockroachDB SERIALIZABLE transaction. Include optimistic aggregate version, writer epoch, policy/fact version validation, idempotency request hash, result, outbox and audit intent. Evaluate OPA outside the transaction and re-evaluate on policy change. Do not make external calls inside retry closures. Test retry injection, commit-success/response-loss, duplicate keys, policy races and contention. Provide a load harness and report measured figures separately from design targets.')

add('federation','Replicate intention, not entire tables.','Component / Federation pipeline','The local outbox captures business intent. The exporter constructs and authorises the smallest useful regional projection.',
section('Pipeline and boundaries',flow([['Atomic outbox','Home transaction writes immutable event UUID, aggregate version, schema version and source snapshot.'],['Local CDC','CockroachDB changefeed emits only into local Kafka. Raw snapshots never enter a global bus.'],['Authorised export','Worker loads latest grant/fence facts, evaluates OPA and produces allow-listed projection fields.'],['Private crossing','mTLS to destination importer; signed permit binds payload digest, region, dataset, generation and expiry.'],['Atomic import','Validate identity/permit/schema and local fence, deduplicate, replace projection, commit audit intent.'],['Reconcile','Compare desired state and destination evidence; repair lag or missing projections without granting new authority.']]))+
section('Event contract',code('''{
  "eventId": "uuid", "customerId": "synthetic-customer-001",
  "sourceRegion": "SG", "destinationRegion": "UK",
  "homeEpoch": 1, "aggregateVersion": 42,
  "policyVersion": 12, "grantGeneration": 3,
  "schemaVersion": 1, "dataset": "customerProfile",
  "operation": "REPLACE_PROJECTION",
  "projectionRevision": 8,
  "payload": {"customerId": "synthetic-customer-001", "displayName": "Demo"}
}''','JSON')+'<p>The projection revision changes for field-policy changes even when business data does not. Persist versions and grant generation per customer, dataset and destination. A newer projection policy can remove fields at the same aggregate version; it cannot accidentally overwrite newer business data with an old snapshot.</p>')+
section('Ordering strategy',table(['Condition','Handling'],[
['Duplicate event','Inbox unique key returns previous acknowledgement.'],['Older data','Ignore data regression while still processing valid fence/policy operations.'],['Old authority','Reject lower grant generation even if aggregate version is higher.'],['Snapshot races update','Full snapshots carry version; delayed initial snapshot cannot replace newer data.'],['Field narrowing','Build a fresh projection from latest source; enforce new visibility immediately, then remove old fields physically.'],['Patch / multi-table extension','Add manifest/aggregate completeness and gap repair; not included in first PoC.']]))+
section('Messaging configuration and backpressure','<p>Use separate regional Kafka clusters with three brokers, replication factor 3, min.insync.replicas 2 and producer acks=all for the HA profile. Export workers repartition by customer where needed; unique outbox event keys do not magically provide customer ordering. Correctness relies on versions and fences, not bus ordering alone.</p><p>Keep retry queues and DLQs at the source. The initial cross-region hop is HTTPS to the importer, so unauthorised payloads are not first persisted into a destination broker. Give revocation/control messages a priority lane; cap snapshot chunk size and worker concurrency. If CDC is down longer than retained history, recover from the retained outbox or a controlled snapshot, never assume missing events are harmless.</p>')+
section('Extension interfaces',code('''interface PolicyDecisionPort { Decision evaluate(TrustedInput input); }
interface SnapshotPort { Snapshot load(CustomerId id, Version min); }
interface ExportPermitPort { Permit acquire(TransferIntent intent); }
interface RegionalTransport { Receipt send(Envelope event, Permit permit); }
interface ReplicaStore { ApplyResult applyAtomically(Envelope event); }
interface ReconcilePort { Plan compare(DesiredState d, ObservedState o); }''','Java contracts')+sources([('CockroachDB CDC message guarantees','https://www.cockroachlabs.com/docs/stable/changefeed-messages')])),
baseprompt+'Build a minimal outbox-to-local-Kafka-to-exporter-to-HTTPS-importer pipeline with synthetic data. Use full projection snapshots, schema versions, event deduplication, aggregate versions, projection revisions, grant generations and home epochs. No global Kafka mirroring. Implement OPA before egress and destination validation. Test duplicate and reordered messages, expired permits, field narrowing without data update, stalled CDC, bootstrap races and destination crash after commit. Add backlog metrics and a bounded reconciliation loop.')

add('lifecycle','A policy change is a tracked operation.','Component / Policy authority & reconciliation','Approval, effective blocking, live deletion and historical disposal are distinct states—not a single green tick.',
section('Desired and observed state',table(['State','Meaning','Required evidence'],[
['DRAFT','Proposed policy only','Validation and impact simulation.'],['PENDING_APPROVAL','Immutable proposal awaits another operator','Maker, proposed hash, current policy version, reason.'],['RECONCILING','Approved desired state committed','Durable jobs; current-generation source and destination receipts.'],['ACTIVE','Required projections established','Grant generation, data version and last applied timestamp.'],['REVOKING','Source blocks new authorisations','Source fence and outstanding permit tracking.'],['ACCESS_BLOCKED','Remote reads/imports fenced or leases expired','Destination receipt or clearly labelled expiry inference.'],['LIVE_PURGED','Current projections removed','Destination deletion transaction receipt.'],['RETENTION_PENDING','History, backups or logs remain','Retention inventory, disposal schedule and exceptions.'],['COMPLETE','Defined disposal obligations satisfied','Evidence references; never implied from a DELETE alone.']]))+
section('Revocation protocol',flow([['Commit revocation','Increment generation, deny new exports and enqueue revoke/audit intents atomically.'],['Fence source','Stop new permits, cancel queued sends and account for in-flight authorisations.'],['Fence receiver','Install generation fence and block reads/imports in the same transaction that removes the live projection.'],['Reconcile evidence','Retry control delivery; acknowledge unreachable state rather than fabricating success.'],['Dispose history','Track MVCC, queue, cache and backup retention. Restore workflows replay current fences before access.']]))+
call('Unavoidable race, explicit semantics','An in-flight payload may arrive after revocation was requested. Do not promise zero transit after the request timestamp. Effective export blocking is declared only after the source barrier and outstanding permits are accounted for. A destination fence prevents resurrection, not historical transmission.')+
section('Maker–checker rules','<p>The approver must differ from the proposer and have the relevant scope. Approval binds to an immutable proposal hash and expected current version. A stale proposal returns conflict and must be simulated again. Emergency deny can use a separately authorised fast path; it may block access immediately but never claim completed erasure.</p><p>Policy widening requires approval. Policy narrowing can follow a faster authorised path, but retention/legal-hold conflicts must surface as unresolved obligations, not a silent exception. Home-region changes are a separate fenced migration workflow.</p>')+
section('Reconciler design','<p>Use CockroachDB-backed jobs with leases, idempotent steps, retry timestamps and bounded backoff. Compare desired policy against observed regional copies. Scope each job by customer/dataset/destination/generation so delayed jobs cannot re-enable a removed grant. Entitlement expiry schedules work even when no business data changes. Never send a customer-keyed denial to a region that never held the customer.</p>'),
baseprompt+'Implement the home policy authority and durable reconciler state machine. Policy changes atomically record expected version, generation, desired state, audit intent and job. Add maker-checker proposal hashes, distinct actors and stale-version conflicts. Implement revocation stages with source barriers, destination fences, unreachable states and retention obligations. Test delayed grant jobs after revoke, multiple overlapping entitlements, expiry without writes, old-backup restoration and honest incomplete status reporting.')

add('observability','See the flow without exporting the customer.','Component / OpenTelemetry','Traces explain a request. Metrics reveal system behaviour. Durable audit proves governed actions. Keep these roles separate.',
section('Regional telemetry architecture',flow([['Instrument','Java OTel agent for HTTP/JDBC plus manual spans for OPA, export, import and reconciliation.'],['Collect locally','OTLP to local agent/collector; apply bounded queues, memory limits and source-side minimisation.'],['Regional gateway','HA collector tier batches, sanitises and routes signals to in-region backends.'],['Store regionally','Tempo or Jaeger for traces, Prometheus-compatible metrics and a regional log store such as Loki.'],['Aggregate deliberately','Optional global infrastructure metrics only after an allow-list review; no customer IDs, trace IDs or exemplar links.']]))+
section('Span and metric model',table(['Signal','Example','Allowed context'],[
['Trace','http.server → policy.evaluate → db.transaction → outbox.append','Service, region, route template, operation and outcome. No payload or raw URL.'],['Async trace','federation.export → federation.import','Use span links for queued work where approved; scrub baggage at every boundary.'],['Metric','federation.replication.lag.seconds','Bounded region/destination/dataset/outcome labels only.'],['Metric','policy.decision.duration / policy.bundle.age','Rule revision in logs/resource metadata rather than unbounded metric labels.'],['Metric','revocation.pending / audit.archive.lag.seconds','Operational counts and ages; no customer dimension.'],['Log','Import rejected: stale_generation','Structured reason, service and regional correlation ID; masked identity.']]))+
section('Collector skeleton',code('''# Illustrative contrib Collector fragment; validate with pinned distribution.
receivers:
  otlp:
    protocols:
      grpc:
        endpoint: 127.0.0.1:4317
processors:
  memory_limiter:
    check_interval: 1s
    limit_mib: 256
    spike_limit_mib: 64
  attributes/remove_sensitive:
    actions:
      - {key: customer.id, action: delete}
      - {key: enduser.id, action: delete}
      - {key: db.statement, action: delete}
      - {key: db.query.text, action: delete}
      - {key: url.full, action: delete}
      - {key: http.url, action: delete}
  batch: {}
exporters:
  otlp/regional:
    endpoint: regional-collector.observability.svc:4317
    tls:
      ca_file: /certs/ca.pem
      cert_file: /certs/client.pem
      key_file: /certs/client-key.pem
service:
  pipelines:
    traces:
      receivers: [otlp]
      processors: [memory_limiter, attributes/remove_sensitive, batch]
      exporters: [otlp/regional]''','YAML')+call('A deny-list is not complete sanitisation','This fragment is an extension skeleton, not a complete privacy configuration. Production must allow-list span, resource, event and log attributes, redact bodies and exceptions, disable SQL/body capture at source, and test with synthetic canaries. Collector mTLS, authentication, RBAC and network policy need full configuration.'))+
section('Sampling and availability decisions','<p>Start with 10% parent-based probabilistic tracing in the PoC. It cannot guarantee retaining every error trace; count all errors with metrics and capture sanitised error logs. If all error traces become a requirement, use regional tail sampling with trace-ID-affine routing, memory sizing and an explicit overload policy. Sampling must never apply to mandatory audit records.</p><p>Telemetry outage should not take down ordinary reads/writes. SDK export is bounded and asynchronous, with dropped-signal metrics. Mandatory audit intent is different: if it cannot be committed durably for a governed mutation, fail that mutation. OPA debug/decision logs supplement rather than replace the transactional audit ledger.</p>')+
section('Dashboards and alerts',table(['Dashboard','Panels / alerts'],[
['Regional health','API p95/p99, errors, DB retries, quorum/replica issues, connection saturation.'],['Federation','Lag, oldest outbox event, retry/DLQ count, rejected permits and drift.'],['Policy','Bundle activation status, invalid bundle attempts, expired facts, deny reasons.'],['Revocation','Oldest pending revoke, unacknowledged destination, live purge versus retention.'],['Telemetry integrity','Collector drops, queue fill, exporter errors and audit archival backlog.']]))+
section('Primary references',sources([('OpenTelemetry gateway pattern','https://opentelemetry.io/docs/collector/deploy/gateway/'),('Handling sensitive data','https://opentelemetry.io/docs/security/handling-sensitive-data/'),('Baggage security implications','https://opentelemetry.io/docs/concepts/signals/baggage/')])),
baseprompt+'Add OpenTelemetry instrumentation to the regional prototype. Use Java agent plus manual policy/export/import/reconcile spans, regional collector pipelines and bounded-cardinality metrics. Apply source-side minimisation and an attribute allow-list across logs, traces, resources and events. Drop baggage at untrusted/cross-region boundaries unless explicitly approved. Supply dashboards and tests that synthetic customer canaries never enter exported telemetry. Keep mandatory audit durable and unsampled. Start with head sampling and document that not all error traces are retained; no false compliance claims.')

add('audit','Evidence has a custody chain.','Component / Audit & retention','Audit decisions and state transitions durably, while keeping the evidence itself within approved boundaries.',
section('Two distinct records',table(['Operational telemetry','Mandatory audit'],[
['May be sampled or dropped within bounded queues','Never sampled; durable intent is committed with governed mutations.'],['Explains latency and failures','Records actor, decision, purpose, policy version and state transition.'],['Regional OTel collectors and monitoring backends','Regional append-only ledger and retention-controlled immutable archive.'],['Short operational retention','Bank-approved retention profile, holds and disposal evidence.']]))+
section('Audit envelope',code('''{
  "auditId": "uuid", "occurredAt": "server-time",
  "region": "SG", "action": "POLICY_REVOKE_REQUESTED",
  "actorRef": "regional-pseudonym", "customerRef": "regional-reference",
  "policyVersion": 13, "grantGeneration": 4,
  "ruleBundleRevision": "rules-2026-10-10.2",
  "decisionId": "regional-decision-id", "reason": "entitlement_removed",
  "operationId": "op-demo-013", "evidenceRefs": []
}''','JSON'))+
section('Custody and completeness','<p>Audit intent is stored in the transaction, then asynchronously archived. Use deterministic IDs, archive receipts and reconciliation to detect gaps. Immutable object retention and restricted write identities provide durable custody; a mutable SQL table alone does not. A hash chain can help detect modifications but does not replace access control, retention enforcement or independent verification.</p><p>OPA decision logging can contain input and output. Use masking policy before shipping it, and do not log payloads to stdout. Audit references, hashes and pseudonyms remain governed metadata. The optional global fleet dashboard receives only vetted aggregates.</p>')+
section('Deletion and restoration inventory',table(['Surface','Control'],[
['Live DB / cache / search','Fenced access, delete projection, verify all registered sinks.'],['MVCC / SST history','Document collection and retention bounds; do not equate SQL DELETE with byte erasure.'],['Kafka / DLQ','Short approved regional retention; no immediate erasure promise from compaction.'],['Backup / archive','Track retention expiry, holds and restore quarantine; key deletion only if scope and recovery effects are understood.'],['Audit','Retain only justified evidence under an explicit policy; surface conflicts with exclusion requests.']]))+
section('Reference',sources([('OPA decision log masking','https://www.openpolicyagent.org/docs/management-decision-logs')])),
baseprompt+'Implement a regional transactional audit outbox and idempotent archive adapter stub. Include operation, policy/rule revision, actor reference, generation and evidence references; no payloads. Track archival receipts and missing IDs. Add masked OPA decision-log configuration and retention inventory interfaces for DB history, queues and backups. Test archive outage, audit-intent write failure, duplicate archival and restore quarantine. Do not claim append-only SQL is immutable storage.')

add('apis','Contracts before integrations.','Technical design / API & data contracts','Keep administrative commands, business commands and federation traffic on separate authenticated surfaces.',
section('Business API',table(['Method / route','Contract','Semantics'],[
['GET /v1/customers/{id}','fields, sourceVersion, replicatedAt, freshness','Purpose and field enforcement; only permitted local customer knowledge.'],['POST /v1/customers/{id}/commands','commandType, payload, expectedVersion; Idempotency-Key','Home-authoritative commit; current policy revalidated.'],['GET /v1/commands/{id}','status, committedVersion, permitted result','Recover unknown outcome after a timeout without duplicating effects.']]))+
section('Control API',table(['Method / route','Purpose'],[
['POST /v1/policies:validate','Schema and consistency validation; excludes own-home rejection.'],['POST /v1/policies:simulate','OPA evaluation + desired placement and field-impact diff; no mutation.'],['POST /v1/policy-proposals','Immutable draft hash and base version.'],['POST /v1/policy-proposals/{id}:approve','Different actor; compare current version; durable policy/job commit.'],['POST /v1/customers/{id}/entitlements','Scoped grant proposal.'],['DELETE /v1/customers/{id}/entitlements/{grantId}','Revocation operation; generation fencing.'],['GET /v1/customers/{id}/federation-status','Desired/observed state, versions, evidence and pending obligations.'],['POST /v1/customers/{id}:reconcile','Idempotent repair, not a permission override.'],['GET /v1/operations/{id}','Precise lifecycle milestones and unresolved destinations.']]))+
section('Internal API',table(['Method / route','Contract'],[
['POST /internal/v1/replication:apply','Signed destination-bound permit + versioned envelope; mTLS exporter identity.'],['POST /internal/v1/replication:revoke','Grant/generation fence; idempotent receipt.'],['POST /internal/v1/replication:status','Scoped observed-version/evidence query; never a global customer enumeration.'],['POST /v1/data/bank/federation/decision','Loopback OPA endpoint; not exposed through public gateways.']]))+
section('Error and concurrency conventions','<p>Use 401 for invalid identity; 403 for denied actions, with generic external messages where customer existence could leak; 409 for optimistic-version or idempotency conflicts; 429 for bounded overload; 503 for unavailable authority or mandatory dependencies. Return 202 for policy lifecycle operations. A network timeout means outcome unknown, not “transaction rolled back”.</p>')+
section('Minimum schema',table(['Table','Key / significant fields'],[
['customer_master','customer_id; home_epoch, aggregate_version, payload'],['customer_policy','customer_id; version, document, effective state'],['entitlement','grant_id; customer, dataset, region, fields, expiry, generation'],['policy_proposal','proposal_id; immutable hash, maker, approver, base version'],['outbox_event','event_id; customer, aggregate version, schema, source snapshot'],['replication_intent','customer + dataset + destination; generation, desired state'],['replica_customer','customer + dataset; data version, projection revision, grant generation'],['inbox_event','source + event_id; applied result'],['revocation_fence','customer + dataset + grant; minimum generation'],['audit_intent / reconcile_job','durable IDs; state, receipt/retry timestamp']]))+
section('Transaction sequence', '''<div class="sequence-diagram"><svg viewBox="0 0 900 390" role="img" aria-label="Sequence: Regional API evaluates with OPA, commits business audit and outbox in home database, returns result, then federation exports asynchronously"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#237762"/></marker></defs><g fill="#173e43"><rect x="30" y="15" width="170" height="43" rx="7"/><rect x="250" y="15" width="170" height="43" rx="7"/><rect x="470" y="15" width="170" height="43" rx="7"/><rect x="690" y="15" width="170" height="43" rx="7"/></g><g fill="#fff" font-size="13" font-family="system-ui" text-anchor="middle"><text x="115" y="42">Regional API</text><text x="335" y="42">Local OPA</text><text x="555" y="42">Home DB</text><text x="775" y="42">Federation</text></g><g stroke="#b5ccc0" stroke-dasharray="4 5"><path d="M115 60V375"/><path d="M335 60V375"/><path d="M555 60V375"/><path d="M775 60V375"/></g><g stroke="#237762" stroke-width="2" marker-end="url(#arrow)" fill="none"><path d="M115 106H335"/><path d="M335 151H115"/><path d="M115 210H555"/><path d="M555 260H115"/><path d="M555 312H775"/></g><g fill="#335b51" font-size="12" font-family="system-ui" text-anchor="middle"><text x="225" y="93">1. Evaluate trusted facts</text><text x="225" y="139">2. Allow + version + fields</text><text x="335" y="198">3. Validate facts; business + audit + outbox</text><text x="335" y="248">4. Committed result + version</text><text x="665" y="300">5. Local CDC, at least once</text><text x="775" y="347">6. Authorised export</text><text x="775" y="366">and atomic import</text></g></svg></div><div class="sequence"><ol><li><b>1.</b> API → OPA: trusted command and current facts</li><li><b>2.</b> OPA → API: decision, fields and policy version</li><li><b>3.</b> API → DB: validate facts; commit business + audit + outbox</li><li><b>4.</b> DB → API: result and aggregate version</li><li><b>5.</b> CDC → exporter: committed event, at least once</li><li><b>6.</b> Exporter → importer: authorised projection; atomic apply</li></ol></div>'''),
baseprompt+'Author OpenAPI 3.1 contracts and JSON Schemas for business, control and internal federation surfaces on this page. Include idempotency, expected versions, 202 operations, generic denial errors, freshness and typed lifecycle evidence. Add a thin client/server skeleton and contract tests only. Prevent customer enumeration from excluded regions. Keep OPA loopback endpoints private; validate integer-safe timestamps and schema evolution.')
add('control-plane','A clear view of where each customer belongs.','UX / Customer residency console','An operator starts with desired versus observed placement, then drills into the policy, projection or evidence behind it.',
'''<div class="demo-banner"><span class="status-dot"></span> INTERACTIVE WIREFRAME · synthetic data · local browser simulation</div>
<div class="console-toolbar"><div><span class="eyebrow">REGIONAL WORKSPACE</span><strong>Singapore / Federation operations</strong></div><label>Customer search<input id="customer-search" placeholder="Search C-001, C-002 or C-003" type="search"></label></div>
<div class="stats"><div><span>Authorised customers</span><strong>3</strong><small>Synthetic Singapore workspace</small></div><div><span>Healthy remote projections</span><strong>1</strong><small>Illustrative current state</small></div><div><span>Pending obligations</span><strong class="amber-text">1</strong><small>UK historical disposal</small></div></div>
<div class="console-split"><div class="customer-list" id="customer-list"></div><div class="customer-detail" id="customer-detail" aria-live="polite"></div></div>
<div id="customer-empty" hidden class="callout">No matching synthetic customer. The real API must not search excluded regional directories.</div>
'''+section('Wireframe design decisions',table(['Element','Operator need','Behaviour'],[
['Desired / observed placement','Spot drift without interpreting log streams','Home, active projection, explicit deny and retention pending have distinct text labels.'],['Policy and generation','Know which authority produced the current copy','Display data version, policy version and grant generation separately.'],['Review policy','Preview consequences before requesting a change','Links to the policy lab; no immediate production mutation.'],['Evidence drawer','Explain the last successful import or revocation','Regional evidence only; no global customer audit search.'],['Global fleet mode','Monitor infrastructure without processing all customers','Show non-identifying cell counts/health only, never unrestricted customer drill-through.']]))+
section('Roles and navigation','<p><b>Operator:</b> inspect and propose. <b>Approver:</b> approve an immutable proposal from a different maker. <b>Auditor:</b> inspect scoped evidence. <b>Platform engineer:</b> inspect bundle/collector infrastructure without automatic customer access. Role switching in the demo illustrates the journey; production roles come from verified identity and server enforcement.</p>')+
section('Accessibility and safety cues','<p>Use persistent labels, keyboard-operable controls, status text in addition to colour, visible conflict/expiry notices and responsive stacking. Keep destructive changes in an impact review. Never show “compliant” merely because an operation was queued or a region stopped responding.</p>'),
baseprompt+'Build the customer-residency console shown here against mocked typed APIs first. Include scoped customer search, desired/observed placement, policy/data/generation versions, freshness and regional evidence. Support keyboard navigation and mobile layouts. Separate roles and disable unapproved actions server-side in the later integration. Do not infer physical deletion from a successful revoke request. Replace synthetic state only after contract tests pass.',group='Experience')

add('policy-lab','Explain the decision before changing the policy.','UX / Policy lab & approval','Explore how storage, processing, business entitlement and explicit denial combine. The live demo is a JavaScript mirror of the documented rule intent—not an OPA runtime.',
'''<div class="demo-banner"><span class="status-dot"></span> POLICY SIMULATOR · synthetic C-001 · authoritative home SG</div>
<div class="lab-grid"><div class="panel"><h2>Proposed United Kingdom entitlement</h2><p class="muted">US remains explicitly denied. Home remains SG.</p><label>Destination<select id="sim-region"><option value="UK">United Kingdom</option><option value="US">United States</option></select></label><label class="check"><input type="checkbox" id="sim-storage" checked> Permit storage in destination</label><label class="check"><input type="checkbox" id="sim-processing" checked> Permit processing in destination</label><label class="check"><input type="checkbox" id="sim-entitlement" checked> Active servicing entitlement</label><label class="check"><input type="checkbox" id="sim-expired"> Customer facts have expired</label><label>Requested fields<select id="sim-fields"><option value="minimal">Customer ID + display name</option><option value="contact">Add contact preferences</option><option value="restricted">Request national ID (denied field)</option></select></label><div class="button-row"><button id="simulate" class="primary">Evaluate proposal</button><button id="reset-sim">Reset</button></div></div><div class="panel decision-panel"><span class="eyebrow">DECISION EXPLANATION</span><div id="sim-result" aria-live="polite"></div><h3>Policy facts preview</h3><pre id="sim-json"></pre></div></div>
<section class="doc-section"><h2>Review and approve</h2><div class="approval-grid"><div><label>Acting identity<select id="acting-role"><option value="maker">Alex — policy maker</option><option value="checker">Sam — policy approver</option></select></label><label>Business reason<input id="change-reason" value="United Kingdom customer servicing requirement"></label><div class="button-row"><button id="propose" class="primary">Submit proposal</button><button id="approve">Approve proposal</button></div><p class="muted">Create as Alex, then switch to Sam. Changes to input invalidate the previous review.</p></div><div id="approval-state" class="review-state" aria-live="polite">No proposal submitted. Evaluate the impact first.</div></div></section>
'''+section('Production authoring workflow',flow([['Compose','Regional form validates schema and creates policy facts; operators do not write arbitrary Rego.'],['Simulate','Backend evaluates actual candidate rule bundle and current facts; show destinations, field removals and obligations.'],['Propose','Persist immutable proposal hash, reason, maker and base policy version.'],['Approve','Different authorised identity confirms the exact hash; stale base version returns 409.'],['Observe','Display operation progress; approval is not proof of completed propagation or purge.']]))+
call('Explicit denial wins','Selecting US with both storage and processing enabled still denies the transfer. This demo keeps the US exclusion fixed to make the precedence visible. Real policy changes that remove an exclusion require a separately reviewed residency-policy change.'),
baseprompt+'Implement the policy lab UI with JSON Schema forms, actual backend OPA simulation and a deterministic impact diff. Include maker-checker approval bound to immutable proposal hash and expected policy version. Show partial field denial distinctly from complete request denial. Add stale-version, same-actor, expired-facts and US-exclusion tests. The current website uses a labelled JavaScript mirror; replace it with OPA-backed API calls, not an unlabelled imitation.',group='Experience')

add('operations','Revocation is a journey with evidence.','UX / Operations & observability','See exactly what has stopped, what has been deleted and what remains subject to retention.',
'''<div class="demo-banner"><span class="status-dot"></span> OPERATION SIMULATOR · SG → UK · synthetic customer C-001</div>
<div class="ops-toolbar"><label>Destination connectivity<select id="destination-state"><option value="online">United Kingdom reachable</option><option value="offline">United Kingdom unreachable</option></select></label><div class="button-row"><button id="start-revoke" class="danger">Request UK revocation</button><button id="advance-revoke">Advance one stage</button><button id="reset-revoke">Reset</button></div></div>
<div id="revoke-status" class="operation-status" aria-live="polite"></div><div id="revoke-timeline" class="timeline"></div>
<section class="doc-section"><div class="section-heading"><h2>Regional observability</h2><span class="pill">ILLUSTRATIVE · NOT LIVE</span></div><div class="stats"><div><span>Local API p95</span><strong>84<span class="unit">ms</span></strong><small>Design target ≤100 ms reads</small></div><div><span>Projection lag</span><strong>1.8<span class="unit">s</span></strong><small>Design target p95 ≤5 s</small></div><div><span>OPA evaluation p95</span><strong>2.4<span class="unit">ms</span></strong><small>Local sidecar decision</small></div></div>
<div class="trace-panel"><div class="trace-head"><strong>Synthetic request trace</strong><span>SG · customer.command · 84 ms</span></div><div class="trace-row"><span>gateway.authorise</span><div><i style="margin-left:0%;width:9%"></i></div><b>7 ms</b></div><div class="trace-row"><span>policy.evaluate</span><div><i style="margin-left:10%;width:4%"></i></div><b>3 ms</b></div><div class="trace-row"><span>db.transaction</span><div><i style="margin-left:15%;width:70%"></i></div><b>59 ms</b></div><div class="trace-row"><span>response.filter</span><div><i style="margin-left:87%;width:13%"></i></div><b>11 ms</b></div><small>Durations illustrate the layout; not benchmark results. Async export is a separate linked trace.</small></div></section>
'''+section('Evidence requirements',table(['Milestone','Display rule'],[
['Export blocked','Show source fence generation and outstanding permit state.'],['Access blocked','Show receiver acknowledgement; if relying on lease expiry, label it as inferred and account for skew.'],['Live data purged','Require destination transaction receipt. Unreachable never becomes purged on a timer.'],['Retention pending','List remaining inventory and due date; distinguish holds.'],['Complete','Require every defined obligation’s evidence. Simulation advance stands in for evidence, not elapsed time.']]))+
call('Operational view versus audit record','Trace sampling may omit a request. This does not remove the corresponding mandatory audit obligation. Every state transition has its own durable regional audit intent; the UI links to evidence only where the operator is authorised.'),
baseprompt+'Build the revocation operation screen with server-supplied milestones, source fence, outstanding permits, destination acknowledgements and retention obligations. Poll operation status with backoff; do not fabricate completion. Add reachable/unreachable and lease-expiry presentations. Connect OTel dashboards only to regional backends and label target versus measured metrics. Test that a disconnected destination cannot be shown as physically purged.',group='Experience')

add('engineering','A thin slice, then deliberate extensions.','Engineering / Delivery prompts','Build the smallest demonstrable system that proves regional custody, policy enforcement and recovery behaviour.',
section('Suggested repository skeleton',table(['Module / directory','Owns','Extension points'],[
['contracts/','OpenAPI, JSON Schema, event versions','Generated clients, schema compatibility gates.'],['policy/','Rego v1 and OPA unit tests','Bundle signing, region exceptions, field-policy rules.'],['business-service/','Home command orchestrator and domain modules','Adapters for existing service repos and common transaction context.'],['control-service/','Policy proposals, approval and reconciler','Entitlement source, retention authority, migration workflow.'],['federation-worker/','Snapshot/export/import/fence loop','CDC transport, large datasets, multi-domain manifests.'],['observability/','Collector config and dashboard definitions','Tail sampling, protected regional backends.'],['infra/','Compose demo and separate K8s/HA manifests','Cloud region/AZ mappings, keys and network controls.'],['tests/','Contracts, Rego, integration, chaos and load','Restore, placement inspection and evidence assertions.']]))+
section('Implementation order',table(['Slice','Deliverable','Acceptance gate'],[
['1 · Contracts and policy','Schemas, OPA rules, signed-bundle skeleton','US deny, expiry and field-deny unit tests pass in actual OPA.'],['2 · Local business transaction','One SG customer command and idempotency','Business/audit/outbox all commit or all roll back.'],['3 · Gateway route','UK local reads and authorised command routing to SG','Spoofed region and gateway bypass are denied.'],['4 · Federation','Local CDC/Kafka, projection exporter/importer','C-001 appears in UK with allowed fields and is absent in US surfaces.'],['5 · Lifecycle','Grant, expiry, field narrowing and revoke','Old events cannot resurrect revoked data; offline purge stays pending.'],['6 · Operations UX','Regional screens against real PoC APIs','Maker-checker, stale proposals and honest milestones work.'],['7 · Observability / evidence','Regional OTel, durable audit and canary scans','No customer canary in global outputs; audit survives exporter outage.'],['8 · Performance / HA','Load and zone-failure exercises','Measured targets, correct retries and local continuity documented.']]))+
section('Core acceptance scenarios', '<ol class="numbered"><li>Create C-001 in SG, allow UK profile fields and explicitly deny US. Inspect database, bus, logs, DLQ, trace and backup test surfaces.</li><li>Update profile; lose importer acknowledgement after commit. Retry produces one final projection and no duplicate side effect.</li><li>Remove contact preference access without a customer write. New reads hide it and the projection is physically narrowed.</li><li>Revoke UK, replay old grants/events, and restore an old replica backup in quarantine. Current fences prevent resurrection.</li><li>Disconnect UK. New export permits stop at home; remote access expires within the stated lease/skew window; deletion remains unconfirmed.</li><li>Change facts between OPA evaluation and business commit. Version validation forces re-evaluation.</li><li>Kill one node/AZ in the separate HA profile; check DB, gateway, worker and bus continuity rather than database health alone.</li><li>Inject customer canaries into request bodies, exception text, URLs and OPA input; prove sanitised telemetry and masking.</li></ol>')+
section('Scope boundaries','<p>The prototype excludes real customer data, production deployment, multi-master conflict resolution, automatic cross-region promotion, global ACID, full retention/legal-hold automation and unbounded dataset federation. It includes enough adapters and tests to make those later decisions concrete.</p>')+
section('Master engineering prompt','<p>Use the copy button below for the coordinating brief, then open each component page for its focused prompt. Complete each acceptance slice before broadening scope. Keep contracts stable across repositories and document any consolidation into shared transaction modules.</p>'),
baseprompt+'''Build this design as a thin end-to-end prototype in the order shown on the Engineering page. Use the dedicated page prompts for gateways, OPA, transactions, federation, lifecycle, telemetry, audit and UX. Start with synthetic C-001 (SG home, UK allowed, US denied). Provide a working local setup, a separate HA profile, automated tests and a short demonstration script. Use local serializable transactions and async outbox/CDC; no remote calls inside retry closures. Make the UI call actual OPA-backed services only after the mocked journey is verified. Report measured performance separately from budgets. Include outstanding risks, explicit revocation semantics, retention limitations and evidence of what was tested. Do not implement a full production banking product.''',group='Deliver')

